create policy "Admins can manage relationships" on public.relationships for all to authenticated using ((auth.jwt() -> 'user_metadata' ->> 'role') = 'admin') with check ((auth.jwt() -> 'user_metadata' ->> 'role') = 'admin');
create policy "Admins can manage occasions" on public.occasions for all to authenticated using ((auth.jwt() -> 'user_metadata' ->> 'role') = 'admin') with check ((auth.jwt() -> 'user_metadata' ->> 'role') = 'admin');
insert into public.relationships (name, emoji, sort_order) values ('Mom','❤️',1),('Dad','💙',2),('Sister','💜',3),('Brother','💚',4),('Best Friend','💛',5),('Couple','💕',6),('Husband / Wife','💖',7),('Grandparents','🤍',8),('Kids','🧸',9),('Family','👨‍👩‍👧‍👦',10) on conflict (name) do nothing;
insert into public.occasions (name, emoji, sort_order) values ('Birthday','🎂',1),('Anniversary','💍',2),('Wedding','💒',3),('Festival','✨',4),('Graduation','🎓',5),('Baby Shower','👶',6),('Thank You','🙏',7),('Special Day','🎁',8) on conflict (name) do nothing;
